await expect(page.getByRole('button', { name: city.name, exact: true })).toBeVisible(); await page.getByRole('button', { name: building.name, exact: true }).click(); await page.getByRole('button', { name: event.name, exact: true }).click(); await expect(page.locator('#entity-name')).toHaveValue(event.name); await editData(page, { ...event.data, summary: textToRichText('場所一覧から同じ建物の出来事を編集した。') }); await page.getByRole('button', { name: '詳細を閉じる', exact: true }).click(); await world(page, '地図・場所・移動');
