    const cityMap = await createMap('街の実画像地図', city.id); cityMapId = cityMap.id; const buildingMap = await createMap('建物の実画像地図', building.id, cityMap.id); buildingMapId = buildingMap.id; await page.getByLabel('表示する地図', { exact: true }).selectOption(cityMapId); await page.getByLabel('地図へピンを追加する場所', { exact: true }).selectOption(building.id); await page.getByLabel('地図ピンの横位置', { exact: true }).fill('0.25'); await page.getByLabel('地図ピンの縦位置', { exact: true }).fill('0.75'); await page.getByRole('button', { name: 'ピン座標を適用', exact: true }).click(); await page.getByRole('button', { name: 'ピンの変更を保存', exact: true }).click(); await expect.poll(async () => (await storedEntity(page, cityMapId, 'map')).data.pins).toMatchObject([{ placeId: building.id, x: .25, y: .75 }]);

