expect(await page.evaluate(() => document.documentElement.scrollWidth - innerWidth)).toBeLessThanOrEqual(1);
    const before = await canvas.evaluate(n => n.scrollLeft);
    await page.locator('.editor-content').hover(); await page.mouse.wheel(0, 240);
    expect(await canvas.evaluate(n => n.scrollLeft)).toBe(before);
    expect(await page.evaluate(() => document.documentElement.scrollWidth - innerWidth)).toBeLessThanOrEqual(1);
    await page.reload(); const saved = await backup(page); expect(findEntity(saved.project, f.shared.id, 'event').data.summary[0].text).toBe('未来の対象をスクロール後に編集');

await timeline(page); const hour = page.getByLabel('年表の表示単位', { exact: true }).locator('option[value="hour"]');
    await expect(hour).toBeDisabled(); await expect(hour).toContainText('時'); expect((await hour.textContent())?.length).toBeGreaterThan(3);
    expect(await authorFingerprint(page)).toBe(before);

await page.getByRole('button', { name: '始点 → 終点をタップで結ぶ', exact: true }).click();
    await page.locator('.common-lane').locator(`button[data-event-id="${f.common.id}"]`).click();
    await expect(page.getByRole('status').filter({ hasText: '始点' }).first()).toBeVisible();
    await page.locator('.common-lane').locator(`button[data-event-id="${f.shared.id}"]`).click();
    const dialog = page.getByRole('dialog', { name: '年表の関係を編集' });
    await dialog.getByLabel('年表の関係の種類', { exact: true }).selectOption('causes'); await dialog.getByRole('button', { name: '関係を保存', exact: true }).click(); await expect(dialog).toHaveCount(0);

const saved = await backup(page); expect(saved.project.relations).toHaveLength(1); id = saved.project.relations[0].id; expect(saved.project.relations[0]).toMatchObject({ fromId: f.common.id, toId: f.shared.id, relationType: 'causes' });
    await timeline(page); await page.locator(`button[data-relation-id="${id}"]`).click();
    const dialog = page.getByRole('dialog', { name: '意味付きの関係を編集' });
    await expect(dialog.getByLabel('関係の始点', { exact: true })).toHaveValue(f.common.id);
    await dialog.getByLabel('関係の種類', { exact: true }).selectOption('requires'); await dialog.getByLabel('関係の始点', { exact: true }).selectOption(f.common.id); await dialog.getByLabel('関係の終点', { exact: true }).selectOption(f.shared.id); await dialog.getByRole('button', { name: '関係を保存', exact: true }).click(); await expect(dialog).toHaveCount(0);
    const updated = await backup(page); expect(updated.project.relations).toHaveLength(1); expect(updated.project.relations[0]).toMatchObject({ id, relationType: 'requires' });

await timeline(page); await page.locator(`button[data-relation-id="${id}"]`).click(); const dialog = page.getByRole('dialog', { name: '意味付きの関係を編集' }); const before = await authorFingerprint(page);
    await dialog.getByLabel('関係の種類', { exact: true }).selectOption('trust');
    await expect(dialog.getByLabel('関係の始点', { exact: true }).locator(`option[value="${f.common.id}"]`)).toHaveCount(0);
    await expect(dialog.getByLabel('関係の終点', { exact: true }).locator('option[value="ffffffff-ffff-4fff-8fff-ffffffffffff"]')).toHaveCount(0);
    await expect(dialog.getByRole('button', { name: '関係を保存', exact: true })).toBeDisabled();
    expect(await authorFingerprint(page)).toBe(before);
    // A disabled selector proves prevention, but this original clause also
    // Requires the computed rejection reason as well as the disabled action.
    await expect(dialog).toContainText(/人物.*人物|人物同士|人物間/);

await page.getByRole('button', { name: '参加者を追加', exact: true }).click(); await page.getByLabel('参加者1', { exact: true }).selectOption(a.id); await page.getByLabel('参加者1の役割', { exact: true }).selectOption('actor');
    await page.getByRole('button', { name: '参加者を追加', exact: true }).click(); await page.getByLabel('参加者2', { exact: true }).selectOption(b.id); await page.getByLabel('参加者2の役割', { exact: true }).selectOption('witness');
    await page.locator('.editor-footer').getByRole('button', { name: '保存する', exact: true }).click(); await expect(page.locator('.editor-save-state')).toContainText('端末内保存済み');
    const saved = await backup(page); await openEntity(page, 'event', event.name); await editData(page, { ...findEntity(saved.project, event.id, 'event').data, authorNotes: textToRichText('目撃だけで真相を知ったとはしない。') });

for (const person of [a, b]) {
      await openEntity(page, 'character', person.name); await page.locator('.references-section').getByRole('button', { name: new RegExp(event.name) }).click(); await expect(page.locator('#entity-name')).toHaveValue(event.name); await page.getByRole('tab', { name: '詳細', exact: true }).click();
      await expect(page.getByLabel('参加者1', { exact: true })).toHaveValue(a.id); await expect(page.getByLabel('参加者2', { exact: true })).toHaveValue(b.id);
    }

await expect(page.getByLabel('参加者1の役割', { exact: true })).toHaveValue('actor'); await expect(page.getByLabel('参加者2の役割', { exact: true })).toHaveValue('witness');
    await expect(page.getByLabel('参加者1の役割', { exact: true }).locator('option')).toContainText(['当事者', '目撃者', '言及される', '情報を得る', '独自の役割']);
    await page.reload(); const saved = await backup(page), registered = findEntity(saved.project, event.id, 'event'); expect(registered.data.participants).toEqual([{ characterId: a.id, role: 'actor' }, { characterId: b.id, role: 'witness' }]); expect(registered.data.authorNotes?.[0].text).toBe('目撃だけで真相を知ったとはしない。'); expect(saved.project.entities.filter(e => e.kind === 'assertion')).toHaveLength(0); await attachObservation(info, 'AT-B08-observed', { eventId: event.id, participants: registered.data.participants, inferredKnowledgeIds: [] });

await page.getByRole('button', { name: `${f.a.name}から${f.b.name}へ、信頼、関係を編集`, exact: true }).click(); const dialog = page.getByRole('dialog', { name: '意味付きの関係を編集' });
    await dialog.getByLabel('関係の種類', { exact: true }).selectOption('related'); await dialog.getByLabel('関係の始点', { exact: true }).selectOption(f.a.id); await dialog.getByLabel('関係の終点', { exact: true }).selectOption(f.b.id); await dialog.getByRole('button', { name: '関係を保存', exact: true }).click(); await expect(dialog).toHaveCount(0);
    await timeline(page); await page.getByRole('button', { name: '全体へ戻る', exact: true }).click(); await page.getByRole('button', { name: f.a.name, exact: true }).click();

await expect(page.locator('#entity-name')).toHaveValue(f.a.name); await expect(page.locator('.detail-panel')).toContainText('関連');
    // The original then requires the relation's period at the opened detail.
    // A relation type alone does not establish that observation.
    await expect(page.locator('.detail-panel')).toContainText(/0\s*(?:tick|〜|～|→).*100/);
    const saved = await backup(page); expect(saved.project.relations[0]).toMatchObject({ id: row.id, relationType: 'related', validity: row.validity }); expect(findEntity(saved.project, group.id, 'group').data).toEqual(group.data); for (const e of [f.a, f.b, f.shared]) expect(findEntity(saved.project, e.id, e.kind).data).toEqual(e.data);
    await attachObservation(info, 'AT-B09-observed', { relationId: row.id, validity: saved.project.relations[0].validity, sourceIds: [f.a.id, f.b.id], placementOnlyPreservedDurableRecords: true });

for (const record of [place, individual, person]) {
      await openEntity(page, record.kind, record.name); await page.locator('.references-section').getByRole('button', { name: new RegExp(event.name) }).click(); await expect(page.locator('#entity-name')).toHaveValue(event.name);
      await page.getByRole('tab', { name: '確認表示', exact: true }).click(); const label = record === person ? '人物' : record === place ? '場所' : '個体'; await page.locator('.detail-panel').getByRole('button', { name: label, exact: true }).click(); await expect(page.locator('#entity-name')).toHaveValue(record.name);
    }

await openEntity(page, 'item', type.name); await page.getByRole('tab', { name: '詳細', exact: true }).click(); await expect(page.getByLabel('物品の扱い', { exact: true })).toHaveValue('type'); await openEntity(page, 'item', individual.name); await page.getByRole('tab', { name: '詳細', exact: true }).click(); await expect(page.getByLabel('物品の扱い', { exact: true })).toHaveValue('instance');
    await reader(page); await page.getByLabel('試読の開始点', { exact: true }).selectOption(start.id); await page.getByRole('button', { name: '試読を始める', exact: true }).click(); await page.getByRole('button', { name: '個体を一度取得', exact: true }).click(); await expect(page.locator('.reader-state-counts')).toContainText('1個'); await page.getByRole('button', { name: '同じ個体を再取得', exact: true }).click(); await expect(page.locator('.reader-page')).toContainText('二重取得'); await expect(page.locator('.reader-state-counts')).toContainText('1個');
    const saved = await backup(page); expect(saved.project.entities.filter(e => e.kind === 'item').map(e => e.id)).toEqual([type.id, individual.id]); expect(findEntity(saved.project, event.id, 'event').data.itemIds).toEqual([individual.id]); expect(saved.project.entities.filter(e => e.kind === 'assertion')).toEqual([]); await attachObservation(info, 'AT-B11-observed', { typeId: type.id, individualId: individual.id, eventId: event.id, duplicateAcquisitionRejected: true });

await navigate(page, /^作品・保存/); await page.getByRole('tab', { name: '完全保存・復元', exact: true }).click(); const before = await authorFingerprint(page), assetsBefore = await durableAssets(page), original = await backup(page);
    const rewrite = (mutate: (files: Record<string, Uint8Array>) => void) => { const files = unzipSync(downloaded); mutate(files); return zipSync(files, { level: 0 }); };
    const bad: { name: string; bytes: Uint8Array; reason: RegExp }[] = [
      { name: 'payload-hash.scenario', bytes: rewrite(files => { files['data/project.json'][4] ^= 1; }), reason: /HASH_MISMATCH|SHA-256|ハッシュ/ },
      { name: 'unsupported-reader.scenario', bytes: rewrite(files => { const manifest = JSON.parse(new TextDecoder().decode(files['manifest.json'])); manifest.minimumReaderVersion = '99.0.0'; files['manifest.json'] = strToU8(JSON.stringify(manifest)); }), reason: /新しいアプリ|FORMAT_UNSUPPORTED/ },
      { name: 'unsafe-path.scenario', bytes: rewrite(files => { files['../outside.json'] = strToU8('{}'); }), reason: /パス|ARCHIVE_INVALID/ },
      { name: 'broken-reference.scenario', bytes: rewrite(files => { const source = JSON.parse(new TextDecoder().decode(files['data/project.json'])); source.entities.find((e: { id: string }) => e.id === event.id).data.locationId = newId(); files['data/project.json'] = strToU8(JSON.stringify(source)); const manifest = JSON.parse(new TextDecoder().decode(files['manifest.json'])); const row = manifest.files.find((f: { path: string }) => f.path === 'data/project.json'); row.byteSize = files['data/project.json'].length; row.sha256 = createHash('sha256').update(files['data/project.json']).digest('hex'); files['manifest.json'] = strToU8(JSON.stringify(manifest)); }), reason: /参照|VALIDATION_FAILED/ },
    ];
    for (const input of bad) { await page.getByLabel('保存ファイルを選ぶ', { exact: true }).setInputFiles({ name: input.name, mimeType: 'application/zip', buffer: Buffer.from(input.bytes) }); await expect(page.locator('.backup-page').getByRole('alert')).toContainText(input.reason); expect(await authorFingerprint(page)).toBe(before); expect(await durableAssets(page)).toBe(assetsBefore); await attachObservation(info, `AT-B12-rejected-${input.name}`, { archiveSha256: createHash('sha256').update(input.bytes).digest('hex'), visibleReason: await page.locator('.backup-page').getByRole('alert').textContent(), unchangedAuthorRecords: true, unchangedAssetBytes: true }); }
    await page.reload(); const after = await backup(page); expect(after.project).toEqual(original.project); expect(after.assets.map(asset => ({ path: asset.path, hash: asset.contentHash, bytes: Array.from(asset.bytes) }))).toEqual(original.assets.map(asset => ({ path: asset.path, hash: asset.contentHash, bytes: Array.from(asset.bytes) })));

await page.getByRole('button', { name: '一手戻る', exact: true }).click(); await page.getByRole('button', { name: '選択肢ゼロへ', exact: true }).click(); await expect(page.locator('.reader-trial-heading')).toContainText('進行不可'); await expect(page.locator('.reader-trial-heading')).not.toContainText('意図した終端'); await page.getByRole('button', { name: '一手戻る', exact: true }).click();
    const stateBefore = await page.locator('.reader-state-counts').textContent(); await page.getByRole('button', { name: '不正効果を試す', exact: true }).click(); await expect(page.locator('.reader-page')).toContainText('物品が不足'); await expect(page.locator('.reader-trial-heading')).not.toContainText('意図した終端'); await expect(page.locator('.runtime-variable').filter({ hasText: counter.name })).toContainText('0'); expect(await page.locator('.reader-state-counts').textContent()).toBe(stateBefore);
    const saved = await backup(page); expect(findEntity(saved.project, counter.id, 'variable').data.initial).toEqual({ type: 'integer', value: 0 }); expect(saved.project.entities.filter(e => e.kind === 'trace')).toEqual([]);

for (const [target, label] of [[quest, '任務'], [lore, '伝承']] as const) {
      await openEntity(page, 'dialogue_line', line.name); await page.getByRole('tab', { name: '確認表示', exact: true }).click(); await page.locator('.detail-panel').getByRole('button', { name: label, exact: true }).click(); await expect(page.locator('#entity-name')).toHaveValue(target.name); await page.locator('.references-section').getByRole('button', { name: new RegExp(line.name) }).click(); await expect(page.locator('#entity-name')).toHaveValue(line.name);
    }
    await openEntity(page, 'variable', state.name); await page.locator('.references-section').getByRole('button', { name: new RegExp(node.name) }).click(); await expect(page.locator('#entity-name')).toHaveValue(node.name);

declared_bindings.source_excerpt:
test('AT-E09 二経路の同じ場面と公開済み小説を世界改訂・制作集計・日付変更で保ち、未設定時間と実装未完了を区別する', async ({ page }, info) => {
  let world = createProject('AT-E09 改訂する共通世界');
  const place = createEntity(world.projectId, 'place', '旧世界設定の城', { body: textToRichText('公開済み小説が参照した旧世界設定。') });
  place.status = 'confirmed'; world.entities.push(place); world = await createWorldSnapshot(world, '小説公開時の旧世界版');
  const worldPin = world.snapshots.at(-1)!;
  let p = createProject('AT-E09 二経路で同じ場面を再利用する作品');
  const event = createEntity(p.projectId, 'event', '再利用場面の世界日付', { time: { mode: 'instant', at: '5', calendarId: p.calendarId }, locationId: place.id });
  const scene = createEntity(p.projectId, 'scene', '二経路で使う一つの制作場面', { body: textToRichText('城の門を開く共通場面。'), eventIds: [event.id] });
  const a = createEntity(p.projectId, 'flow_node', '再利用経路A', { nodeType: 'entry', sceneId: scene.id });
  const b = createEntity(p.projectId, 'flow_node', '再利用経路B', { nodeType: 'entry', sceneId: scene.id });
  const end = createEntity(p.projectId, 'flow_node', '二経路の終端', { nodeType: 'terminal', terminalReason: '同じ場面を体験して終了' });
  const ea = createEntity(p.projectId, 'flow_edge', '経路Aを終える', { fromId: a.id, toId: end.id, label: '経路Aを終える' });
  const eb = createEntity(p.projectId, 'flow_edge', '経路Bを終える', { fromId: b.id, toId: end.id, label: '経路Bを終える' });
  const graph = createEntity(p.projectId, 'flow_graph', '同じ場面の二経路', { nodeIds: [a.id, b.id, end.id], edgeIds: [ea.id, eb.id], entryIds: [a.id, b.id], exitIds: [end.id] });
  const deadline = { date: '2026-12-31', timeZone: 'Asia/Tokyo' };
  const written = createEntity(p.projectId, 'production_task', '同じ場面の執筆完了', { targetIds: [scene.id], stage: 'writing', progress: 'done', deadline });
  const implementation = createEntity(p.projectId, 'production_task', '執筆済み場面の実装未完了', { targetIds: [scene.id], stage: 'implementation', progress: 'todo', dependsOn: [written.id], deadline });
